  const name = cltControls.distribution;

  if (name === "Uniform") {
    return {
      name,
      mean: 0,
      sd: 1,
      domain: [-2.1, 2.1],
      makeSampler: rng =&gt; () =&gt; Math.sqrt(3) * (2 * rng() - 1)
    };
  }

  if (name === "Exponential") {
    return {
      name,
      mean: 1,
      sd: 1,
      domain: [0, 7],
      makeSampler: rng =&gt; () =&gt; -Math.log(Math.max(1e-12, 1 - rng()))
