  }

  if (name === "Bimodal mixture") {
    const componentMean = 1.6;
    const componentSd = 0.35;
    return {
      name,
      mean: 0,
      sd: Math.sqrt(componentMean ** 2 + componentSd ** 2),
      domain: [-3.2, 3.2],
      makeSampler: rng =&gt; {
        const normal = d3.randomNormal.source(rng)(0, componentSd);
        return () =&gt; (rng() &lt; 0.5 ? -componentMean : componentMean) + normal();
      }
    };
  }

  return {
    name: "Normal",
    mean: 0,
    sd: 1,
    domain: [-4, 4],
    makeSampler: rng =&gt; d3.randomNormal.source(rng)(0, 1)
