Definition 4.10 (Consistency) A sequence of estimators \hat{\theta}_n is consistent for \theta if

\hat{\theta}_n \;\xrightarrow{p}\; \theta
\quad \text{as } n \to \infty,

that is, it converges in probability 1.17 to the true parameter value.




Intuitively, a consistent estimator will “home in” on the true parameter as the sample size grows.
The definition is about the probability of missing any fixed tolerance band around \theta. The next visualisation shows that probability directly and lets you compare consistency with two tempting counterexamples.


Show Visualisation: consistency and an epsilon band

consTarget = 0

consParametersAt = (scenario, n) =&gt; {
  if (scenario === "Asymptotically unbiased only") {
    return {mean: 2 / Math.sqrt(n), sd: 0.8};
  }
  if (scenario === "Unbiased but not consistent") {
    return {mean: 0, sd: 0.8};
  }
  return {mean: 1 / Math.sqrt(n), sd: 1 / Math.sqrt(n)};
}

consErf = value =&gt; {
  const sign = value &lt; 0 ? -1 : 1;
  const x = Math.abs(value);
  const t = 1 / (1 + 0.3275911 * x);
  const polynomial = (((((1.061405429 * t - 1.453152027) * t) +
    1.421413741) * t - 0.284496736) * t + 0.254829592) * t;
  return sign * (1 - polynomial * Math.exp(-x * x));
}

consNormalCdf = value =&gt; 0.5 * (1 + consErf(value / Math.sqrt(2)))

consOutsideProbability = (scenario, n, epsilon) =&gt; {
  const parameters = consParametersAt(scenario, n);
  const lowerZ = (consTarget - epsilon - parameters.mean) / parameters.sd;
  const upperZ = (consTarget + epsilon - parameters.mean) / parameters.sd;
  return consNormalCdf(lowerZ) + 1 - consNormalCdf(upperZ);
}

consParameters = consParametersAt(consControls.scenario, consControls.n)
consProbabilityOutside = consOutsideProbability(
