viewof leftPanel = {
  const wrap = html`&lt;div class="ojs-plot-frame" style="
    max-width: ${plotW}px;
    aspect-ratio: ${plotW} / ${plotH};
    line-height: 0;
  "&gt;&lt;/div&gt;`;

