    .attr("width", plotW).attr("height", plotH)
    .style("position", "absolute").style("left", "0").style("top", "0")
    .style("width", "100%").style("height", "100%")
    .style("color", "var(--plot-fg)")
    .style("pointer-events", "none");



  const xScale = d3.scaleLinear().domain(muDomain).range([marginLeft, marginLeft + innerW]);
  const yScale = d3.scaleLinear().domain(sig2Domain).range([marginTop + innerH, marginTop]);

  const vline = svg.append("line")
  .attr("x1", xScale(muhat)).attr("x2", xScale(muhat))
  .attr("y1", marginTop).attr("y2", marginTop + innerH)
  .attr("stroke", "currentColor");

  const hline = svg.append("line")
  .attr("x1", marginLeft).attr("x2", marginLeft + innerW)
  .attr("y1", yScale(sigma2hat)).attr("y2", yScale(sigma2hat))
  .attr("stroke", "currentColor");

  wrap.append(svg.node());

  // Hitbox fills wrapper; subtract margins in code
  const hit = html`&lt;div style="
    position:absolute; left:0; top:0; width:100%; height:100%;
    cursor:crosshair; background:transparent; touch-action:none;
  "&gt;&lt;/div&gt;`;
  hit.tabIndex = 0;
  hit.setAttribute("role", "application");
  hit.setAttribute("aria-label", "Log-likelihood surface. Use the arrow keys to move the mu and sigma-squared probe.");
  wrap.append(hit);

  const state = { x: muhat, y: sigma2hat };
  let dragging = false;
  wrap.value = { ...state };

  function emit() {
    wrap.value = { ...state };
    wrap.dispatchEvent(new CustomEvent("input", { bubbles: true }));
  }

  function setFromPoint(clientX, clientY, notify = true) {
    const r = hit.getBoundingClientRect();
    const scaleX = plotW / r.width;
    const scaleY = plotH / r.height;
    let px = (clientX - r.left) * scaleX;
    let py = (clientY - r.top) * scaleY;
    px = Math.min(Math.max(0, px - marginLeft), innerW);
    py = Math.min(Math.max(0, py - marginTop), innerH);
    state.x = muDomain[0] + (px / innerW) * (muDomain[1] - muDomain[0]);
    state.y = sig2Domain[1] - (py / innerH) * (sig2Domain[1] - sig2Domain[0]);
    vline.attr("x1", xScale(state.x)).attr("x2", xScale(state.x));
    hline.attr("y1", yScale(state.y)).attr("y2", yScale(state.y));
    if (notify) emit();
  }

  // Follow the newest pointer position on each animation frame. Retaining the
  // first event in a busy frame makes the probe visibly trail the pointer.
  let raf = 0;
  let pendingPoint = null;
  function scheduleUpdate(e) {
    pendingPoint = [e.clientX, e.clientY];
    if (raf) return;
    raf = requestAnimationFrame(() =&gt; {
      raf = 0;
      const [clientX, clientY] = pendingPoint;
      pendingPoint = null;
      setFromPoint(clientX, clientY);
    });
  }

  hit.addEventListener("pointerdown", (e) =&gt; {
    dragging = true;
    setFromPoint(e.clientX, e.clientY);
    hit.setPointerCapture(e.pointerId);
  });

  hit.addEventListener("pointermove", (e) =&gt; {
    if (dragging) scheduleUpdate(e);
  });

  const endDrag = (e) =&gt; {
    if (!dragging) return;
    dragging = false;
    if (raf) {
      cancelAnimationFrame(raf);
      raf = 0;
    }
    pendingPoint = null;
    setFromPoint(e.clientX, e.clientY);
  };
  hit.addEventListener("pointerup", endDrag);
  hit.addEventListener("pointercancel", endDrag);

  hit.addEventListener("keydown", (e) =&gt; {
    const xStep = (muDomain[1] - muDomain[0]) / 50;
    const yStep = (sig2Domain[1] - sig2Domain[0]) / 50;
    if (e.key === "ArrowLeft") state.x -= xStep;
    else if (e.key === "ArrowRight") state.x += xStep;
    else if (e.key === "ArrowDown") state.y -= yStep;
    else if (e.key === "ArrowUp") state.y += yStep;
    else return;

    e.preventDefault();
    state.x = Math.min(Math.max(muDomain[0], state.x), muDomain[1]);
    state.y = Math.min(Math.max(sig2Domain[0], state.y), sig2Domain[1]);
    vline.attr("x1", xScale(state.x)).attr("x2", xScale(state.x));
    hline.attr("y1", yScale(state.y)).attr("y2", yScale(state.y));
    emit();
  });

  // initial notify
  queueMicrotask(emit);

  return wrap;
}

