          fill: colHist, fillOpacity: 0.35, stroke: colHist, strokeOpacity: 0.7 }
      ),
      // fitted normal density
      Plot.line(curve, { x: "x", y: "y", stroke: colCurve, strokeWidth: 2.5 }),
      // baseline
      Plot.ruleY([0], { stroke: gridCol, strokeOpacity: 0.4 })
    ]
  });
}
















