distSpec = {
  const p = distParams;
  const fmt = (x, digits = 2) =&gt; Number.isFinite(x) ? x.toFixed(digits) : "undefined";
  let data, stats, kind = "continuous", xDomain;

  switch (distChoice) {
    case "bernoulli": {
      data = [0, 1].map(x =&gt; ({ x, y: x ? p.p : 1 - p.p }));
      stats = md`**Mean** ${tex`=p`} ${fmt(p.p)}; **variance** ${tex`=p(1-p)`} ${fmt(p.p * (1-p.p), 3)}.`;
      kind = "discrete";
      break;
    }
    case "binomial": {
      data = Array.from({ length: p.n + 1 }, (_, x) =&gt; ({ x, y: binomPMF(p.n, p.p, x) }));
      stats = md`**Mean** ${tex`=np`} ${fmt(p.n*p.p)}; **variance** ${tex`=np(1-p)`} ${fmt(p.n*p.p*(1-p.p))}.`;
      kind = "discrete";
      break;
    }
    case "poisson": {
      const hi = Math.max(10, Math.ceil(p.lambda + 5*Math.sqrt(p.lambda)));
      data = Array.from({ length: hi + 1 }, (_, x) =&gt; ({ x, y: poisPMF(p.lambda, x) }));
      stats = md`**Mean and variance** ${tex`=\lambda`} ${fmt(p.lambda)}.`;
      kind = "discrete";
      break;
    }
    case "geometric": {
      const hi = Math.min(60, Math.max(10, Math.ceil(Math.log(0.01)/Math.log(1-p.p))));
      data = Array.from({ length: hi }, (_, i) =&gt; ({ x: i+1, y: geomPMF1(p.p, i+1) }));
      stats = md`**Mean** ${tex`=1/p`} ${fmt(1/p.p)}; **variance** ${tex`=(1-p)/p^2`} ${fmt((1-p.p)/(p.p**2))}.`;
      kind = "discrete";
      break;
    }
    case "negativeBinomial": {
      const mean = p.r/p.p;
      const sd = Math.sqrt(p.r*(1-p.p)/(p.p**2));
      const hi = Math.min(100, Math.max(p.r+8, Math.ceil(mean+5*sd)));
      data = Array.from({ length: hi-p.r+1 }, (_, i) =&gt; ({ x: p.r+i, y: negbinPMF(p.r, p.p, p.r+i) }));
      stats = md`**Mean** ${tex`=r/p`} ${fmt(mean)}; **variance** ${tex`=r(1-p)/p^2`} ${fmt(sd**2)}.`;
      kind = "discrete";
      break;
    }
    case "uniform": {
      const pad = 0.15*(p.b-p.a);
      xDomain = [p.a-pad, p.b+pad];
      data = linspace(xDomain[0], xDomain[1]).map(x =&gt; ({ x, y: unifPDF(x, p.a, p.b) }));
      stats = md`**Mean** ${tex`=(a+b)/2`} ${fmt((p.a+p.b)/2)}; **variance** ${tex`=(b-a)^2/12`} ${fmt((p.b-p.a)**2/12)}.`;
      break;
    }
    case "exponential": {
      xDomain = domainExp(p.lambda);
      data = linspace(...xDomain).map(x =&gt; ({ x, y: expPDF(x, p.lambda) }));
      stats = md`**Mean** ${tex`=1/\lambda`} ${fmt(1/p.lambda)}; **variance** ${tex`=1/\lambda^2`} ${fmt(1/(p.lambda**2))}.`;
      break;
    }
    case "gamma": {
      xDomain = domainGamma(p.a, p.b);
      data = linspace(...xDomain).map(x =&gt; ({ x, y: gammaPDF(x, p.a, p.b) }));
      stats = md`**Mean** ${tex`=a/b`} ${fmt(p.a/p.b)}; **variance** ${tex`=a/b^2`} ${fmt(p.a/(p.b**2))}.`;
      break;
    }
    case "inverseGamma": {
      const mean = p.b/(p.a-1);
      const variance = p.a &gt; 2 ? p.b**2/((p.a-1)**2*(p.a-2)) : Infinity;
      const hi = Math.max(4, Math.min(60, Number.isFinite(variance) ? mean+6*Math.sqrt(variance) : 5*mean));
      xDomain = [0, hi];
      data = linspace(...xDomain).map(x =&gt; ({ x, y: x &lt;= 0 ? 0 : Math.exp(p.a*Math.log(p.b)-logGamma(p.a)-(p.a+1)*Math.log(x)-p.b/x) }));
      stats = md`**Mean** ${tex`=b/(a-1)`} ${fmt(mean)}; **variance** ${p.a &gt; 2 ? tex`=b^2/[(a-1)^2(a-2)]\ ${fmt(variance)}` : md`is undefined for ${tex`a\leq2`}`}.`;
      break;
    }
    case "normal": {
      xDomain = domainNormal(p.mu, p.sigma);
      data = linspace(...xDomain).map(x =&gt; ({ x, y: normPDF(x, p.mu, p.sigma) }));
      stats = md`**Mean** ${tex`=\mu`} ${fmt(p.mu)}; **variance** ${tex`=\sigma^2`} ${fmt(p.sigma**2)}.`;
      break;
    }
    case "lognormal": {
      const mean = Math.exp(p.mu+p.sigma**2/2);
      const variance = (Math.exp(p.sigma**2)-1)*Math.exp(2*p.mu+p.sigma**2);
      xDomain = [0, Math.max(4, mean+5*Math.sqrt(variance))];
      data = linspace(...xDomain).map(x =&gt; ({ x, y: lognormPDF(x, p.mu, p.sigma) }));
      stats = md`**Mean** ${tex`=e^{\mu+\sigma^2/2}`} ${fmt(mean)}; **variance** ${tex`=(e^{\sigma^2}-1)e^{2\mu+\sigma^2}`} ${fmt(variance)}.`;
      break;
    }
    case "chiSquared": {
      xDomain = [0, Math.max(8, p.nu+6*Math.sqrt(2*p.nu))];
      data = linspace(...xDomain).map(x =&gt; ({ x, y: chisqPDF(x, p.nu) }));
      stats = md`**Mean** ${tex`=\nu`} ${fmt(p.nu)}; **variance** ${tex`=2\nu`} ${fmt(2*p.nu)}.`;
      break;
    }
    case "studentT": {
      xDomain = [-6, 6];
      data = linspace(...xDomain).map(x =&gt; ({ x, y: tPDF(x, p.nu) }));
      const variance = p.nu &gt; 2 ? p.nu/(p.nu-2) : Infinity;
      stats = md`**Mean** ${p.nu &gt; 1 ? tex`=0` : md`is undefined`}; **variance** ${p.nu &gt; 2 ? tex`=\nu/(\nu-2)\ ${fmt(variance)}` : md`is not finite for ${tex`\nu\leq2`}`}.`;
      break;
    }
    case "f": {
      const mean = p.d2 &gt; 2 ? p.d2/(p.d2-2) : Infinity;
      xDomain = [0, Math.max(6, Number.isFinite(mean) ? 5*mean : 10)];
      data = linspace(...xDomain).map(x =&gt; ({ x, y: fPDF(x, p.d1, p.d2) }));
      stats = md`**Mean** ${p.d2 &gt; 2 ? tex`=d_2/(d_2-2)\ ${fmt(mean)}` : md`is undefined for ${tex`d_2\leq2`}`}.`;
      break;
    }
    case "beta": {
      xDomain = [0, 1];
      data = linspace(...xDomain).map(x =&gt; ({ x, y: betaPDF(x, p.a, p.b) }));
      const mean = p.a/(p.a+p.b);
      const variance = p.a*p.b/((p.a+p.b)**2*(p.a+p.b+1));
      stats = md`**Mean** ${tex`=a/(a+b)`} ${fmt(mean)}; **variance** ${tex`=ab/[(a+b)^2(a+b+1)]`} ${fmt(variance, 3)}.`;
      break;
    }
    case "weibull": {
      const mean = p.lambda*Math.exp(logGamma(1+1/p.k));
      const variance = p.lambda**2*(Math.exp(logGamma(1+2/p.k))-Math.exp(2*logGamma(1+1/p.k)));
      xDomain = [0, Math.max(4, mean+5*Math.sqrt(variance))];
      data = linspace(...xDomain).map(x =&gt; ({ x, y: x &lt;= 0 ? 0 : (p.k/p.lambda)*(x/p.lambda)**(p.k-1)*Math.exp(-(x/p.lambda)**p.k) }));
      stats = md`**Mean** ${tex`=\lambda\Gamma(1+1/k)`} ${fmt(mean)}; **variance** ${fmt(variance)}.`;
      break;
    }
  }

  return { ...distMeta[distChoice], data, stats, kind, xDomain };
}
